/**
 * Attachment metadata plus the storage quota guard.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, wouldExceedLimit
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { issueResource, requireFound } from "./_support";
import type {
  CreateAttachmentInput,
  DeleteAttachmentInput,
} from "@/schemas/attachment";
import type { IssueId, OrgId } from "@/types/common";
import type { IssueAttachment } from "@/types/issue";
import type { Actor } from "@/types/member";
  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const usage = await usageRepo.getUsage(input.orgId);
  const requestedMb = Math.ceil(input.sizeBytes / BYTES_PER_MB);

  if (
    wouldExceedLimit(org.plan, "storageMb", usage.storageMbUsed, requestedMb)
  ) {
    throw new Error(
      `Plan ${org.plan} has no room for another ${requestedMb} MB`,
    );
  }

  const attachment = await attachmentRepo.insertAttachment(
    input,
    actor.userId,
  );
  await usageRepo.incrementUsage(input.orgId, { storageMbUsed: requestedMb });

  return attachment;
}

/** Removing an attachment gives the megabytes back to the quota. */
export async function removeAttachment(
  actor: Actor,
  input: DeleteAttachmentInput,
): Promise<void> {
  assertOrgScope(actor, input.orgId);

  const attachment = requireFound(
    await findAttachment(input.orgId, input.attachmentId),
    "Attachment",
    input.attachmentId,
  );

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, attachment.issueId),
    "Issue",
    attachment.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  await attachmentRepo.deleteAttachment(input.orgId, input.attachmentId);
  await usageRepo.incrementUsage(input.orgId, {
    storageMbUsed: -Math.ceil(attachment.sizeBytes / BYTES_PER_MB),
  });
}

/**
 * The attachment repository only reads by issue, because that is the only way
 * the UI ever reaches one. A delete arrives with just an id, so the org's
 * issues are walked until the row turns up.
 */
async function findAttachment(
  orgId: OrgId,
  attachmentId: string,
): Promise<IssueAttachment | null> {
---
/**
 * Soft-delete filtering.
 *
 * Archived rows stay in the table and disappear from every default read. The
 * cases below pin both halves of that: an archived issue is invisible unless
 * `includeArchived` is set, and archiving a project cascades to its issues.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { AlreadyArchivedError } from "@/lib/soft-delete";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let tenant: Tenant;
let live: Issue;
let archived: Issue;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("softdelete");

  live = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title: "Still open" }),
  );

  const doomed = await issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, tenant.project.id, { title: "Archived away" }),
  );

  archived = await issueService.archiveIssue(
    tenant.actors.member,
    tenant.org.id,
    doomed.id,
  );
});

afterAll(() => {
  cleanup();
});

describe("archived issues", () => {
  it("marks the row rather than deleting it", async () => {
    expect(archived.archivedAt).not.toBeNull();

    const stillThere = await issueRepo.findIssueById(
      tenant.org.id,
      archived.id,
    );
    expect(stillThere?.id).toBe(archived.id);
  });

  it("is excluded from the default listing", async () => {
    const page = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });

    expect(page.items.map((issue) => issue.id)).toEqual([live.id]);
    expect(page.total).toBe(1);
  });

  it("reappears when the caller opts in", async () => {
    const page = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
      includeArchived: true,
    });

    expect(page.total).toBe(2);
    expect(page.items.map((issue) => issue.id).sort()).toEqual(
      [live.id, archived.id].sort(),
    );
  });

  it("is excluded from the per-project count the quota reads", async () => {
    await expect(
      issueRepo.countIssues(tenant.org.id, tenant.project.id),
    ).resolves.toBe(1);

    await expect(
      issueRepo.countIssues(tenant.org.id, tenant.project.id, {
        includeArchived: true,
      }),
    ).resolves.toBe(2);
  });

  it("is excluded from the board columns", async () => {
    const columns = await issueRepo.listBoardColumns(
      tenant.org.id,
      tenant.project.id,
    );
    const ids = columns.flatMap((column) => column.issues.map((i) => i.id));

    expect(ids).toEqual([live.id]);
  });

  it("keeps its issue number reserved", async () => {
    await expect(
      issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id),
    ).resolves.toBe(3);
  });

  it("refuses to be archived twice", async () => {
    await expect(
      issueService.archiveIssue(
        tenant.actors.member,
        tenant.org.id,
        archived.id,
      ),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });
});

describe("archiving a project", () => {
  it("cascades to the project's live issues", async () => {
    const scratch = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Scratch",
      slug: "scratch",
      key: "SCR",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, scratch.id, { title: "Doomed with project" }),
    );

    const result = await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: scratch.id,
      archiveIssues: true,
    });

    expect(result.archivedAt).not.toBeNull();
    await expect(
      issueRepo.countIssues(tenant.org.id, scratch.id),
    ).resolves.toBe(0);
    await expect(
      issueRepo.countIssues(tenant.org.id, scratch.id, {
        includeArchived: true,
      }),
    ).resolves.toBe(1);

    const listed = await projectRepo.listProjects({
      orgId: tenant.org.id,
      limit: 25,
      cursor: null,
    });
    expect(listed.items.map((project) => project.id)).not.toContain(scratch.id);
  });
});
