/** Guard for archive actions, so double-archiving is a domain-level conflict. */
export function assertNotArchived(
  entity: string,
  id: string,
  row: SoftDeletable,
): void {
  if (isArchived(row)) {
    throw new AlreadyArchivedError(entity, id);
  }
}

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * The instant before which an archive has outlived the retention window. A
 * row archived at or before it is expired: no longer restorable, and purged by
 * the retention sweep. Restore and sweep both read this one definition.
 */
export function retentionCutoff(now: Date, retentionDays: number): IsoTimestamp {
  return toIsoTimestamp(new Date(now.getTime() - retentionDays * MS_PER_DAY));
}

/** Why a restore was refused. Each reason maps to one guard in the service. */
export type RestoreRefusalReason =
  | "not_archived"
  | "expired"
  | "project_archived"
  | "quota";

export class RestoreRefusedError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly entity: string,
    readonly id: string,
    readonly reason: RestoreRefusalReason,
  ) {
    super(`${entity} ${id} cannot be restored (${reason}).`);
    this.name = "RestoreRefusedError";
  }
}

