/** What one purge removed, so the caller can clean the index and the quota. */
export interface PurgedIssue {
  readonly issueId: IssueId;
  readonly commentIds: readonly CommentId[];
  /** Sum of each attachment's size rounded up to whole MB, as counted on upload. */
  readonly storageMb: number;
}

/**
 * Permanently deletes one archived issue with its label links, comments and
 * attachments, in one transaction. Before the row goes, the project's
 * high-water mark is raised to its highest number so far, which keeps the
 * purged number from being handed out again.
 */
export async function purgeIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<PurgedIssue> {
  return getDb().transaction((tx) => {
    const issue = tx
      .select()
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();
    if (!issue) throw new Error(`Issue ${issueId} not found`);

    const highest = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, issue.projectId),
        ),
      )
      .get();
    const counter = tx
      .select({ value: issueNumberCounters.lastNumber })
      .from(issueNumberCounters)
      .where(eq(issueNumberCounters.projectId, issue.projectId))
      .get();
    const lastNumber = Math.max(highest?.value ?? 0, counter?.value ?? 0);
    tx.insert(issueNumberCounters)
      .values({ orgId, projectId: issue.projectId, lastNumber })
      .onConflictDoUpdate({
        target: issueNumberCounters.projectId,
        set: { lastNumber },
      })
      .run();

    const commentRows = tx
      .select({ id: comments.id })
      .from(comments)
      .where(
        and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId)),
      )
      .all();

    const attachmentRows = tx
      .select({ sizeBytes: attachments.sizeBytes })
      .from(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          eq(attachments.issueId, issueId),
        ),
      )
      .all();

    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.issueId, issueId),
        ),
      )
      .run();
    tx.delete(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          eq(attachments.issueId, issueId),
        ),
      )
      .run();
    tx.delete(comments)
      .where(
        and(orgPredicate(comments.orgId, orgId), eq(comments.issueId, issueId)),
      )
      .run();

    const deleted = tx
      .delete(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .returning({ id: issues.id })
      .all();
    if (deleted.length === 0) throw new Error(`Issue ${issueId} not found`);

    return {
      issueId,
      commentIds: commentRows.map((row) => row.id as CommentId),
      storageMb: attachmentRows.reduce(
        (total, row) => total + Math.ceil(row.sizeBytes / BYTES_PER_MB),
        0,
      ),
    };
  });
}

/** Cascade behind `ProjectService.archiveProject`; returns the row count. */''')

