/**
 * Permanently removes issues whose retention window has closed.
 *
 * Must call (do not reimplement): getPlanLimits, retentionCutoff
 */
import { getPlanLimits } from "@/config/plan-limits";
import { createLogger } from "@/lib/logger";
import { retentionCutoff } from "@/lib/soft-delete";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";

const ORG_BATCH = 25;

const logger = createLogger("cleanup-archived-job");

/**
 * The retention sweep. An archived issue can be restored for as long as the
 * plan's `retentionDays` allows; once that window closes it is expired and this
 * sweep deletes it for good, with its labels, comments, attachments and search
 * documents. Its number stays reserved, and its attachments' megabytes go back
 * to the storage quota. The audit log is purged on the same cut-off.
 */
export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
  return runJob("cleanup-archived", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org) continue;

      const { retentionDays } = getPlanLimits(org.plan);
      const cutoff = retentionCutoff(now, retentionDays);

      const expired = await issueRepo.listExpiredIssueIds(orgId, cutoff);

      for (const issueId of expired) {
        try {
          const purged = await issueRepo.purgeIssue(orgId, issueId);

          await searchRepo.deleteSearchDocument(orgId, "issue", purged.issueId);
          for (const commentId of purged.commentIds) {
            await searchRepo.deleteSearchDocument(orgId, "comment", commentId);
          }
          if (purged.storageMb > 0) {
            await usageRepo.incrementUsage(orgId, {
              storageMbUsed: -purged.storageMb,
            });
          }
          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("issue purge failed", {
            orgId,
            issueId,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }

      try {
        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
        result.processed += purged;
      } catch (error) {
        result.failed += 1;
        logger.error("activity purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}
EOF
