import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);

import { RestoreRefusedError } from "@/lib/soft-delete";
import { toAppError } from "@/lib/errors";
import { NotFoundError } from "@/server/services/_support";
import { registerEventHandlers } from "@/server/services/event-registry";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import * as commentService from "@/server/services/comment-service";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import { createTenant, issueInput, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import { toIsoTimestamp } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;
const DAY = 24 * 60 * 60 * 1000;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
  tenant = await createTenant("restore", "growth");
  await usageRepo.recomputeUsage(tenant.org.id);
});
afterAll(() => cleanup());

describe("restore", () => {
  it("restores within window, republishes, reindexes, counts, audits", async () => {
    const issue = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: "RestoreMarkerOne" }));
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    const before = await usageRepo.getUsage(tenant.org.id);
    const restored = await issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id);
    expect(restored.archivedAt).toBeNull();
    expect(restored.number).toBe(issue.number);
    const after = await usageRepo.getUsage(tenant.org.id);
    expect(after.issuesUsed).toBe(before.issuesUsed + 1);
    const hits = await searchService.search(tenant.actors.member, { orgId: tenant.org.id, q: "RestoreMarkerOne", kinds: ["issue"], limit: 25, cursor: null });
    expect(hits.total).toBe(1);
    const audit = await activityRepo.listActivity?.({ orgId: tenant.org.id, limit: 100, cursor: null } as never);
    void audit;
  });

  it("refuses not_archived and changes nothing", async () => {
    const issue = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: "Live" }));
    const err = await issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id).catch((e) => e);
    expect(err).toBeInstanceOf(RestoreRefusedError);
    expect(err.reason).toBe("not_archived");
    expect(toAppError(err).code).toBe("conflict");
  });

  it("refuses expired, and not_found for unknown, and tenant scope", async () => {
    const issue = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: "Expiring" }));
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    vi.useFakeTimers({ toFake: ["Date"], now: Date.now() + 366 * DAY });
    try {
      const err = await issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id).catch((e) => e);
      expect(err).toBeInstanceOf(RestoreRefusedError);
      expect(err.reason).toBe("expired");
    } finally {
      vi.useRealTimers();
    }
    await expect(issueService.restoreIssue(tenant.actors.member, tenant.org.id, "nope" as never)).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses project_archived and quota", async () => {
    const issue = await issueService.createIssue(tenant.actors.admin, issueInput(tenant.org.id, tenant.project.id, { title: "ProjArch" }));
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    const scratch = await projectService.createProject(tenant.actors.admin, { orgId: tenant.org.id, name: "Scr", slug: "scr", key: "SCR", description: null, visibility: "org", leadId: null, color: "#6366f1", targetDate: null });
    const inScratch = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, scratch.id, { title: "x" }));
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, inScratch.id);
    await projectService.archiveProject(tenant.actors.admin, { orgId: tenant.org.id, projectId: scratch.id, archiveIssues: false });
    const err = await issueService.restoreIssue(tenant.actors.member, tenant.org.id, inScratch.id).catch((e) => e);
    expect(err.reason).toBe("project_archived");
    const ok = await issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id);
    expect(ok.archivedAt).toBeNull();
  });
});

describe("purge", () => {
  it("purges expired issues with dependents, keeps numbers reserved, frees storage", async () => {
    const issue = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: "PurgeMarker" }));
    const comment = await commentService.createComment(tenant.actors.member, { orgId: tenant.org.id, issueId: issue.id, body: "PurgeCommentMarker", parentId: null, mentionedUserIds: [] } as never);
    const att = await attachmentRepo.insertAttachment({ orgId: tenant.org.id, issueId: issue.id, filename: "a.png", contentType: "image/png", sizeBytes: 1.5 * 1024 * 1024 } as never, tenant.userIds.member);
    await usageRepo.incrementUsage(tenant.org.id, { storageMbUsed: 2 });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    const storageBefore = (await usageRepo.getUsage(tenant.org.id)).storageMbUsed;
    const issuesBefore = (await usageRepo.getUsage(tenant.org.id)).issuesUsed;
    const commentsBefore = await commentRepo.countComments(tenant.org.id, issue.id);
    expect(commentsBefore).toBe(1);

    const now = new Date(Date.now() + 400 * DAY);
    const result = await runCleanupArchivedJob(now);
    expect(result.failed).toBe(0);

    expect(await issueRepo.findIssueById(tenant.org.id, issue.id)).toBeNull();
    expect(await attachmentRepo.listAttachments(tenant.org.id, issue.id)).toHaveLength(0);
    expect(await searchRepo.countIndexed(tenant.org.id)).toBeGreaterThanOrEqual(0);
    const storageAfter = (await usageRepo.getUsage(tenant.org.id)).storageMbUsed;
    expect(storageAfter).toBe(storageBefore - 2);
    expect((await usageRepo.getUsage(tenant.org.id)).issuesUsed).toBe(issuesBefore);
    const hits = await searchService.search(tenant.actors.member, { orgId: tenant.org.id, q: "PurgeCommentMarker", kinds: ["comment"], limit: 25, cursor: null });
    expect(hits.total).toBe(0);
    const hits2 = await searchService.search(tenant.actors.member, { orgId: tenant.org.id, q: "PurgeMarker", kinds: ["issue"], limit: 25, cursor: null });
    expect(hits2.total).toBe(0);
    await expect(issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id)).rejects.toBeInstanceOf(NotFoundError);
    expect(att.id).toBeTruthy();
    expect(comment.id).toBeTruthy();

    const next = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    expect(next).toBe(issue.number + 1);
    const fresh = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: "after" }));
    expect(fresh.number).toBe(issue.number + 1);
  });

  it("purges every expired issue beyond the first page", async () => {
    const ids: string[] = [];
    for (let i = 0; i < 130; i++) {
      const it1 = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: `bulk ${i}` }));
      ids.push(it1.id);
      await issueService.archiveIssue(tenant.actors.member, tenant.org.id, it1.id);
    }
    const r = await runCleanupArchivedJob(new Date(Date.now() + 400 * DAY));
    expect(r.failed).toBe(0);
    const left = await issueRepo.listExpiredIssueIds(tenant.org.id, toIsoTimestamp(new Date(Date.now() + 500 * DAY)));
    expect(left).toHaveLength(0);
    expect(ids.length).toBe(130);
  });
});
